    /**
     * 发送工作通知（异步发送企业会话消息）
     * @param params 发送工作通知参数
     * @returns 发送结果
     * @see https://open.dingtalk.com/document/development/asynchronous-sending-of-enterprise-session-messages
     */
    async sendCorpConversationMsg(params) {
        console.log(`${LOG_PREFIX} sendCorpConversationMsg 开始: msgtype=${params.msg.msgtype}`);
        const tokenResult = await this.getAccessToken(params.adapterKey);
        if (!tokenResult.success || !tokenResult.accessToken) {
            return {
                success: false,
                message: tokenResult.message || '获取 accessToken 失败',
            };
        }
        // 获取 agentId：优先使用参数传入，否则从环境变量获取
        const agentId = params.agentId || Number(this.getAgentId(params.adapterKey));
        if (!agentId) {
            return {
                success: false,
                message: '未配置微应用 AgentID（环境变量 DINGTALK_AGENT_ID 或参数 agentId）' + (params.adapterKey ? `（adapterKey: ${params.adapterKey}）` : ''),
            };
        }
        if (!params.useridList || params.useridList.length === 0) {
            return {
                success: false,
                message: '接收者不能为空，请指定 useridList',
            };
        }
        try {
            const url = `https://oapi.dingtalk.com/topapi/message/corpconversation/asyncsend_v2?access_token=${tokenResult.accessToken}`;
            const requestBody = {
                agent_id: agentId,
                msg: params.msg,
                userid_list: params.useridList.join(','),
                to_all_user: false,
            };
            const response = await fetch(url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(requestBody),
            });
            if (!response.ok) {
                const errorText = await response.text();
                console.error(`${LOG_PREFIX} sendCorpConversationMsg 失败:`, errorText);
                return {
                    success: false,
                    message: `发送工作通知失败: HTTP ${response.status}`,
                };
            }
            const data = await response.json();
            if (data.errcode !== 0) {
                return {
                    success: false,
                    message: data.errmsg || '发送工作通知失败',
                    code: data.errcode.toString(),
                    requestId: data.request_id,
                };
            }
            console.log(`${LOG_PREFIX} sendCorpConversationMsg 成功: taskId=${data.task_id}`);
            return {
                success: true,
                message: '发送工作通知成功',
                taskId: data.task_id,
                requestId: data.request_id,
            };
        }
        catch (error) {
            console.error(`${LOG_PREFIX} sendCorpConversationMsg 异常:`, error);
            return {
                success: false,
                message: this.formatError(error, '发送工作通知异常'),
            };
        }
    }
